        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = safe_get(observation, "unclaimed_cells")
        if not targets:
            targets = safe_get(observation, "opponent_territory")
        if not targets:
            targets = safe_get(observation, "neutral_cells")
        target = nearest_point(targets, self_pos)
        if target is not None:
            return step_toward(self_pos, target)
        if opp_pos is not None:
            return step_toward(self_pos, opp_pos)
        return [0, 0]

